bool SaveWorkUseCase::execute(const SaveWorkDto &saveWorkDto) const
{
    if (saveWorkDto.fileName.isEmpty())
        throw std::runtime_error("File name is empty");

    if (!saveWorkDto.overwrite && QFileInfo::exists(saveWorkDto.fileName))
        throw std::runtime_error("File already exists and overwrite is not set");

    // saveDatabaseToFile handles its own checkpoint/copy/cleanup cycle.
    // No UoW transaction needed, no entity data is modified.
    if (!m_uow->saveDatabaseToFile(saveWorkDto.fileName))
        throw std::runtime_error("Failed to save database to file: " + saveWorkDto.fileName.toStdString());

    m_uow->publishSaveWorkSignal();
    return true;
}

